import { getImage } from "gatsby-plugin-image"
import type { IGatsbyImageData } from "gatsby-plugin-image"

/** 条目内单张照片：图片 + 可选的单张说明 + 首页标记 */
interface PhotoImage {
  image: IGatsbyImageData
  note?: string
  /** 指定本张代表相册上首页（进入候选池） */
  featured?: boolean
  /** 钉到首页指定资源位，见 HOME_PHOTO_POSITIONS；隐含 featured */
  position?: string
}

/** 照片条目：单图（images 长度 1）或专题（images 长度 > 1） */
export interface PhotoItem {
  slug: string
  title: string
  note?: string
  /** 相册日期（YYYY-MM-DD）；仅查询里选了 date 的调用方有值 */
  date?: string
  cover: IGatsbyImageData
  /** cover 在 images 中的下标，用于 lightbox 深链直接预览 */
  coverIndex: number
  /** cover 图上声明的首页资源位（未声明为 undefined） */
  position?: string
  images: PhotoImage[]
}

/**
 * 首页照片资源位（坑位）。在相册 frontmatter 的某张照片上
 * 写 `position: <名称>` 即钉到对应坑位；未钉的坑位由 featured 候选池
 * 按 date 倒序回填。
 * - cover：封面右侧竖幅
 * - lead：照片散页主图（大幅）
 * - side-1 / side-2：散页右侧小幅（自上而下）
 */
const HOME_PHOTO_POSITIONS = [
  "cover",
  "lead",
  "side-1",
  "side-2",
] as const

export type HomePhotoPosition = (typeof HOME_PHOTO_POSITIONS)[number]

export const isHomePhotoPosition = (
  value: string
): value is HomePhotoPosition =>
  (HOME_PHOTO_POSITIONS as readonly string[]).includes(value)

/** /photos/ 深链 hash：index > 0 时携带图序号，lightbox 直接预览该张 */
export const photoHash = (slug: string, index = 0): string =>
  `#${encodeURIComponent(slug)}${index > 0 ? `:${index}` : ""}`

/** allMarkdownRemark 节点的最小形状，photos 页与首页查询共同满足 */
export interface PhotoNode {
  frontmatter: {
    title: string
    note?: string
    date?: string
    photos?: {
      src?: {
        childImageSharp?: {
          gatsbyImageData: IGatsbyImageData
        }
      }
      note?: string
      featured?: boolean
      position?: string
    }[]
  }
  parent: {
    relativeDirectory: string
  }
}

/**
 * markdown 节点 → PhotoItem。封面（代表图）取法：
 * 声明了 position 的图 > featured 图 > 第一张；
 * 没有任何有效图片的条目返回 null（调用方过滤）。
 */
export const toPhotoItem = (node: PhotoNode): PhotoItem | null => {
  const images = (node.frontmatter.photos ?? [])
    .map((p): PhotoImage | null => {
      const image = getImage(p.src?.childImageSharp ?? null)
      return image
        ? { image, note: p.note, featured: p.featured, position: p.position }
        : null
    })
    .filter((i): i is PhotoImage => i !== null)
  if (images.length === 0) return null
  const segments = node.parent.relativeDirectory.split("/")
  const positioned = images.findIndex((i) => Boolean(i.position))
  const featured = images.findIndex((i) => Boolean(i.featured))
  const coverIndex = positioned >= 0 ? positioned : featured >= 0 ? featured : 0
  return {
    slug: segments[segments.length - 1],
    title: node.frontmatter.title,
    note: node.frontmatter.note,
    date: node.frontmatter.date,
    cover: images[coverIndex].image,
    coverIndex,
    position: images[coverIndex].position,
    images,
  }
}

export { default as PhotoSpread } from "./PhotoSpread"
export { default as PhotoGallery } from "./PhotoGallery"
