import React from "react"
import { Link } from "gatsby"
import { GatsbyImage } from "gatsby-plugin-image"
import type { PhotoItem } from "./index"
import { photoHash } from "./index"

interface PhotoSpreadProps {
  photos: PhotoItem[]
}

/**
 * 首页照片散页：杂志式不对称网格——一张大幅 + 两张竖叠小幅，
 * 照片直接落在页面底色上，下方衬线图注；不用任何卡片/外壳。
 * 无照片时整体不渲染（调用方也可自行判断，双保险）。
 * 桌面端右栏两图改为拉伸填充（fill）：右栏总高跟随左图，上下边严格对齐。
 */
function PhotoSpread({ photos }: PhotoSpreadProps): React.ReactElement | null {
  if (photos.length === 0) return null

  const [lead, ...rest] = photos
  const small = rest.slice(0, 2)

  const renderCaption = (photo: PhotoItem): React.ReactElement => (
    <figcaption className="mt-2 flex items-baseline justify-between gap-3">
      <span className="shrink-0 font-serif text-sm text-foreground">
        {photo.title}
      </span>
      {photo.note && (
        <span className="truncate text-xs text-foreground-subtle">
          {photo.note}
        </span>
      )}
    </figcaption>
  )

  const renderFrame = (
    photo: PhotoItem,
    aspectClass: string,
    fill = false
  ): React.ReactElement => (
    <figure
      key={photo.slug}
      className={fill ? "lg:flex lg:min-h-0 lg:flex-1 lg:flex-col" : undefined}
    >
      <Link
        to={`/photos/${photoHash(photo.slug, photo.coverIndex)}`}
        aria-label={`查看照片「${photo.title}」及更多照片`}
        className={`group block overflow-hidden rounded-[3px]${
          fill ? " lg:relative lg:min-h-0 lg:flex-1" : ""
        }`}
      >
        <GatsbyImage
          image={photo.cover}
          alt={photo.title}
          className={`${aspectClass} w-full transition-transform duration-500 group-hover:scale-[1.02] motion-reduce:transition-none motion-reduce:scale-none${
            fill ? " lg:absolute lg:inset-0 lg:h-full" : ""
          }`}
          imgStyle={{ objectFit: "cover" }}
        />
      </Link>
      {renderCaption(photo)}
    </figure>
  )

  // 仅一张照片时通栏横幅；两张时主图 + 单张侧图
  if (small.length === 0) {
    return (
      <section aria-label="精选照片">
        {renderFrame(lead, "aspect-21/9")}
        <div className="mt-4 text-right">
          <Link to="/photos/" className="link-underline text-xs text-accent">
            全部照片 →
          </Link>
        </div>
      </section>
    )
  }

  return (
    <section aria-label="精选照片">
      <div className="grid gap-5 sm:gap-6 lg:grid-cols-5">
        <div className="lg:col-span-3">{renderFrame(lead, "aspect-3/2")}</div>
        {/* 移动端两图并排；桌面端竖叠且拉伸对齐左栏总高 */}
        <div className="grid grid-cols-2 gap-5 sm:gap-6 lg:col-span-2 lg:flex lg:flex-col">
          {small.map((p) =>
            renderFrame(p, "aspect-4/3 lg:aspect-auto", true)
          )}
        </div>
      </div>
      <div className="mt-4 text-right">
        <Link to="/photos/" className="link-underline text-xs text-accent">
          全部照片 →
        </Link>
      </div>
    </section>
  )
}

export default PhotoSpread
