import React, { useCallback, useEffect, useRef, useState } from "react"
import { GatsbyImage } from "gatsby-plugin-image"
import { CaretLeft, CaretRight, Images, X } from "@phosphor-icons/react"
import IconWrapper from "../icons/IconWrapper"
import type { PhotoItem } from "./index"

interface PhotoGalleryProps {
  photos: PhotoItem[]
}

/** lightbox 关闭过渡时长，与 duration-200 对齐 */
const CLOSE_TRANSITION_MS = 200

/** 触摸滑动触发切换的最小水平位移（px），且需大于垂直位移 */
const SWIPE_THRESHOLD_PX = 50

const prefersReducedMotion = (): boolean =>
  typeof window !== "undefined" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches

/** lightbox 焦点：第几个条目 + 条目内第几张 */
interface LightboxFocus {
  item: number
  image: number
}

/**
 * 瀑布流画廊 + lightbox。
 * 条目可以是单图（images 长度 1）或专题（多张，封面带张数角标）；
 * lightbox 的左右切换严格限定在当前条目内循环。
 * 遮罩用主题 token（bg-background-95 + 毛玻璃），双主题均成立；
 * 开关只做 opacity 过渡，reduced-motion 下直接显示/隐藏。
 */
function PhotoGallery({ photos }: PhotoGalleryProps): React.ReactElement {
  const [focus, setFocus] = useState<LightboxFocus | null>(null)
  const [visible, setVisible] = useState(false)
  const touchStart = useRef<{ x: number; y: number } | null>(null)

  const replaceHash = (slug: string | null) => {
    if (typeof window === "undefined") return
    const url = slug
      ? `${window.location.pathname}#${encodeURIComponent(slug)}`
      : window.location.pathname
    window.history.replaceState(null, "", url)
  }

  const open = (item: number) => {
    setFocus({ item, image: 0 })
    replaceHash(photos[item]?.slug ?? null)
    if (prefersReducedMotion()) {
      setVisible(true)
      return
    }
    // 双 rAF：等首帧以 opacity-0 渲染后再触发过渡
    requestAnimationFrame(() =>
      requestAnimationFrame(() => setVisible(true))
    )
  }

  const close = useCallback(() => {
    replaceHash(null)
    if (prefersReducedMotion()) {
      setVisible(false)
      setFocus(null)
      return
    }
    setVisible(false)
    window.setTimeout(() => setFocus(null), CLOSE_TRANSITION_MS)
  }, [])

  // 深链：/photos/#条目slug[:图序号] 直达对应条目（可选指定第几张）的
  // lightbox 预览（如首页目录的照片帖、照片散页的指定图）
  useEffect(() => {
    if (typeof window === "undefined") return
    const raw = decodeURIComponent(window.location.hash.slice(1))
    if (!raw) return
    const matched = raw.match(/^(.*):(\d+)$/)
    const slug = matched ? matched[1] : raw
    const index = photos.findIndex((p) => p.slug === slug)
    if (index >= 0) {
      const image = matched
        ? Math.min(parseInt(matched[2], 10), photos[index].images.length - 1)
        : 0
      setFocus({ item: index, image })
      setVisible(true)
    }
    // 仅挂载时消费一次 hash；后续开关走 open/close
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const step = useCallback(
    (delta: number) => {
      setFocus((current) => {
        if (current === null) return current
        const count = photos[current.item].images.length
        return {
          item: current.item,
          image: (current.image + delta + count) % count,
        }
      })
    },
    [photos]
  )

  const onTouchStart = (event: React.TouchEvent) => {
    const touch = event.touches[0]
    touchStart.current = { x: touch.clientX, y: touch.clientY }
  }

  const onTouchEnd = (event: React.TouchEvent) => {
    const start = touchStart.current
    touchStart.current = null
    if (!start) return
    const touch = event.changedTouches[0]
    const dx = touch.clientX - start.x
    const dy = touch.clientY - start.y
    // 水平位移主导且超过阈值才切换，避免误触上下滚动
    if (Math.abs(dx) >= SWIPE_THRESHOLD_PX && Math.abs(dx) > Math.abs(dy)) {
      step(dx < 0 ? 1 : -1)
    }
  }

  const isOpen = focus !== null

  useEffect(() => {
    if (!isOpen) return
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") close()
      else if (event.key === "ArrowLeft") step(-1)
      else if (event.key === "ArrowRight") step(1)
    }
    document.addEventListener("keydown", onKeyDown)
    document.body.style.overflow = "hidden"
    return () => {
      document.removeEventListener("keydown", onKeyDown)
      document.body.style.overflow = "unset"
    }
  }, [isOpen, close, step])

  const active = focus !== null ? photos[focus.item] : null
  const activeImage = focus !== null && active ? active.images[focus.image] : null

  return (
    <>
      {/* CSS columns 瀑布流；专题卡片右上角叠张数角标 */}
      <div className="columns-2 sm:columns-3 gap-4">
        {photos.map((photo, index) => (
          <figure key={photo.slug} className="mb-4 break-inside-avoid">
            <button
              type="button"
              onClick={() => open(index)}
              aria-label={
                photo.images.length > 1
                  ? `查看专题：${photo.title}，共 ${photo.images.length} 张`
                  : `查看照片：${photo.title}`
              }
              className="relative block w-full rounded-xl overflow-hidden shadow-xs hover:shadow-md transition-shadow duration-200 motion-reduce:transition-none focus:outline-hidden focus:ring-2 focus:ring-accent"
            >
              <GatsbyImage
                image={photo.cover}
                alt={photo.title}
                className="w-full"
              />
              {photo.images.length > 1 && (
                <span className="absolute top-2 right-2 inline-flex items-center gap-1 rounded-full bg-background-95 backdrop-blur-xs px-2 py-0.5 text-xs text-foreground">
                  <IconWrapper icon={Images} size={12} weight="bold" />
                  {photo.images.length} 张
                </span>
              )}
            </button>
            <figcaption className="mt-2 px-1">
              <span className="block text-sm font-medium text-foreground">
                {photo.title}
              </span>
              {photo.note && (
                <span className="block text-xs text-foreground-muted mt-0.5">
                  {photo.note}
                </span>
              )}
            </figcaption>
          </figure>
        ))}
      </div>

      {/* Lightbox：fixed 遮罩 + 大图 + 注脚 + ESC/点击遮罩关闭 + 条目内左右切换 */}
      {active && activeImage && focus && (
        <div
          role="dialog"
          aria-modal="true"
          aria-label={`照片：${active.title}`}
          onClick={close}
          onTouchStart={onTouchStart}
          onTouchEnd={onTouchEnd}
          className={`fixed inset-0 z-60 flex flex-col items-center justify-center p-4 sm:p-8 bg-background-95 backdrop-blur-md transition-opacity duration-200 motion-reduce:transition-none ${
            visible ? "opacity-100" : "opacity-0"
          }`}
        >
          <button
            type="button"
            onClick={close}
            aria-label="关闭"
            className="absolute top-4 right-4 inline-flex items-center justify-center w-10 h-10 rounded-lg bg-background-card text-foreground hover:text-accent transition-colors duration-200"
          >
            <IconWrapper icon={X} size={20} weight="bold" />
          </button>

          {active.images.length > 1 && (
            <>
              <button
                type="button"
                onClick={(event) => {
                  event.stopPropagation()
                  step(-1)
                }}
                aria-label="上一张"
                className="absolute left-2 sm:left-6 top-1/2 -translate-y-1/2 inline-flex items-center justify-center w-10 h-10 rounded-full bg-background-card text-foreground hover:text-accent transition-colors duration-200"
              >
                <IconWrapper icon={CaretLeft} size={22} weight="bold" />
              </button>
              <button
                type="button"
                onClick={(event) => {
                  event.stopPropagation()
                  step(1)
                }}
                aria-label="下一张"
                className="absolute right-2 sm:right-6 top-1/2 -translate-y-1/2 inline-flex items-center justify-center w-10 h-10 rounded-full bg-background-card text-foreground hover:text-accent transition-colors duration-200"
              >
                <IconWrapper icon={CaretRight} size={22} weight="bold" />
              </button>
            </>
          )}

          <div
            className="max-w-4xl w-full flex flex-col items-center"
            onClick={(event) => event.stopPropagation()}
          >
            <GatsbyImage
              image={activeImage.image}
              alt={activeImage.note ?? active.title}
              objectFit="contain"
              className="w-full max-h-[70vh] rounded-xl shadow-lg"
            />
            <div className="mt-4 text-center">
              <p className="text-base font-medium text-foreground font-serif">
                {active.title}
              </p>
              {active.note && (
                <p className="text-sm text-foreground-muted mt-1">
                  {active.note}
                </p>
              )}
              {activeImage.note && (
                <p className="text-sm text-foreground-subtle mt-1">
                  {activeImage.note}
                </p>
              )}
              {active.images.length > 1 && (
                <p className="text-xs text-foreground-muted mt-1 tabular-nums">
                  {focus.image + 1} / {active.images.length}
                </p>
              )}
            </div>
          </div>
        </div>
      )}
    </>
  )
}

export default PhotoGallery
